    53|  padding: 12px 24px;
    54|  border-radius: 8px;
    55|  border: 1px solid #3b82f6;
    56|  text-decoration: none;
    57|  font-weight: 600;
    58|  cursor: pointer;
    59|  font-size: 16px;
    60|}
    61|
    62|/* Home --------------------------------------------------------- */
    63|.hero {
    64|  text-align: center;
    65|  padding: 80px 20px;
    66|  background: #f9fafb;
    67|}
