    79|  display: flex;
    80|  gap: 24px;
    81|  padding: 60px 40px;
    82|  max-width: 1100px;
    83|  margin: 0 auto;
    84|}
    85|.feature {
    86|  flex: 1;
    87|  padding: 24px;
    88|  background: #f3f4f6;
    89|  border-radius: 8px;
    90|}
    91|.feature h3 { font-size: 20px; margin-bottom: 8px; }
    92|.feature p  { color: #4b5563; }
    93|
    94|/* Pricing ------------------------------------------------------ */
    95|.page-title {
    96|  text-align: center;
    97|  font-size: 36px;
    98|  margin: 60px 0 40px;
    99|}
   100|.cards {
   101|  display: flex;
   102|  gap: 24px;
   103|  justify-content: center;
   104|  padding: 0 40px 80px;
   105|  max-width: 1100px;
   106|  margin: 0 auto;
   107|}
   108|.card {
   109|  flex: 1;
