   129|.about {
   130|  max-width: 900px;
   131|  margin: 0 auto;
   132|  padding: 0 20px 80px;
   133|}
   134|.about-lead {
   135|  font-size: 18px;
   136|  color: #4b5563;
   137|  text-align: center;
   138|  margin-bottom: 48px;
   139|  line-height: 1.35;
   140|}
   141|.team {
   142|  display: flex;
   143|  gap: 40px;
   144|  justify-content: center;
   145|}
   146|.member {
   147|  text-align: center;
   148|}
   149|.avatar {
   150|  width: 100px;
   151|  height: 100px;
   152|  border-radius: 50%;
   153|  border: 1px solid #cbd5e1;
   154|  margin: 0 auto 12px;
   155|}
   156|.name { font-weight: 600; font-size: 16px; }
   157|.role { color: #6b7280; font-size: 14px; }
   158|
   159|/* Contact ------------------------------------------------------ */
   160|.contact {
   161|  max-width: 360px;
   162|  margin: 0 auto;
   163|  padding: 0 20px 80px;
   164|}
   165|.contact-form {
   166|  display: flex;
   167|  flex-direction: column;
   168|  gap: 16px;
   169|}
   170|.contact-form label {
   171|  display: flex;
   172|  flex-direction: column;
   173|  gap: 6px;
   174|  font-weight: 500;
   175|  color: #374151;
   176|}
