   178|.contact-form textarea {
   179|  padding: 10px 12px;
   180|  border: 1px solid #ef4444;
   181|  border-radius: 6px;
   182|  font-size: 15px;
   183|  font-family: inherit;
   184|}
   185|.submit-btn {
   186|  margin-top: 8px;
   187|  align-self: flex-start;
   188|  background: #94a3b8;
   189|}
   190|
   191|/* Footer ------------------------------------------------------- */
   192|.footer {
   193|  text-align: center;
   194|  padding: 24px;
   195|  color: #6b7280;
   196|  border-top: 1px solid #e5e7eb;
